using System;using UnityEngine;
namespace LWS.TruckDerby {public static class DerbyFixtures {
 public static int Run(){int checks=0;void C(bool ok,string message){checks++;if(!ok)throw new InvalidOperationException("Derby rule fixture: "+message);}var rules=new DerbyRules();rules.Reset(8);C(rules.Remaining==8&&rules.Heat==1,"eight alive");for(int i=0;i<7;i++)C(rules.Eliminate(i,"FIXTURE")&&!rules.Eliminate(i,"DUPLICATE"),"single elimination "+i);C(rules.FinishStep()&&rules.HeatWinner==7&&rules.wins[7]==1,"survivor wins once");C(!rules.FinishStep()&&!rules.Eliminate(7,"LATE")&&rules.wins[7]==1,"locked survivor cannot explode later");rules.NextHeat();for(int i=0;i<8;i++)rules.Eliminate(i,"SAME STEP");C(rules.FinishStep()&&rules.HeatWinner<0&&rules.wins[7]==1,"full same-step wipe draws");for(int r=0;r<2;r++){rules.NextHeat();for(int i=0;i<7;i++)rules.Eliminate(i,"FIXTURE");C(rules.FinishStep(),"next heat");}C(rules.Winner==7&&rules.wins[7]==3,"first to three");rules.Reset(2);C(rules.Remaining==2&&rules.Winner<0&&rules.wins[7]==0,"rematch clears all old state");
 var damage=new DerbyDamageState();C(DerbyDamageState.Impact(2,7400,7400,100000)==0,"incidental low normal speed ignored");C(DerbyDamageState.Impact(10,7400,7400,0)==0,"unsubstantiated zero impulse ignored");float hit=DerbyDamageState.Impact(10,7400,7400,37000);C(hit>0&&hit<.65f,"effective mass normal energy damage bounded");C(DerbyDamageState.Impact(100000,7400,0,1e9f)<=.65f,"pathological speed capped");damage.Apply(DerbyZone.Front,hit,0);float front=damage.zones[0];C(damage.Engine>0&&damage.wheels[0]>0&&damage.Structure>0,"front engine wheel structure attribution");var rear=new DerbyDamageState();rear.Apply(DerbyZone.Rear,hit);C(rear.zones[1]>0&&rear.zones[1]<front&&rear.Structure>0,"rear protection never invulnerability");damage.Reset();C(damage.Hits==0&&damage.Engine==0&&damage.Structure==0&&damage.wheels[0]==0,"damage reset clears zones and wheels");
 var watch=new DerbyMotionWatch();watch.Reset(Vector3.zero);for(int i=0;i<250;i++)C(!watch.Tick(new Vector3(Mathf.Sin(i)*.002f,0,0),.019f),"tiny vibration never starts a moving grace");C(watch.Tick(Vector3.zero,.3f),"real stationary chassis explodes after five seconds");watch.Reset(Vector3.zero);for(int i=1;i<=500;i++)C(!watch.Tick(Vector3.right*i*.025f,.02f),"real net movement resets inactivity "+i);watch.Reset(Vector3.zero);watch.Tick(Vector3.zero,4.5f);C(!watch.Tick(Vector3.zero,0)&&watch.Stopped==4.5f,"paused dt does not consume stop clock");watch.Reset(Vector3.zero);C(watch.Stopped==0,"new heat resets inactivity");return checks;}
}}
